import { ClientKafka } from '@nestjs/microservices';
import { AgentService } from '../../agent/agent.service';

/**
 * A shared type definition for questions generated by the AI.
 * In a real application, this might be part of a shared DTO library.
 */
export interface AIQuestion {
  id: string;
  question: string;
  category: 'Market' | 'Finance' | 'Operations';
}

// --- Activity Input/Output Interfaces ---

export interface BusinessPlanAnalysisInput {
  businessPlan: string;
}

export interface BusinessPlanFeedbackOutput {
  feedback: string;
}

export interface BusinessPlanQuestionsOutput {
  questions: AIQuestion[];
}

export interface NotifyAnalysisCompleteInput {
  userId: string;
  feedback: string;
  questions: AIQuestion[];
}

/**
 * Creates an object containing the Temporal Activities for the Quantum Weaver workflow.
 * This factory function allows for dependency injection of services (like AgentService
 * and the Kafka client) into the activities.
 * The Temporal worker that executes these activities will be responsible for creating
 * the service instances and passing them to this factory.
 *
 * @param agentService An instance of the AgentService to interact with AI models.
 * @param kafkaClient An instance of the NestJS ClientKafka to emit events.
 * @returns An object where keys are activity names and values are the activity functions.
 */
export function createQuantumWeaverActivities(
  agentService: AgentService,
  kafkaClient: ClientKafka,
) {
  return {
    /**
     * Activity: Generates high-level feedback for a given business plan using an AI model.
     * This is a distinct, retryable step in the workflow.
     * @param input - Contains the business plan string.
     * @returns An object containing the generated feedback text.
     */
    async generateBusinessPlanFeedback(
      input: BusinessPlanAnalysisInput,
    ): Promise<BusinessPlanFeedbackOutput> {
      const { businessPlan } = input;
      const feedbackPrompt = `Provide concise, high-level feedback on the following business plan: "${businessPlan}"`;
      const feedback = await agentService.generateText({ prompt: feedbackPrompt });
      return { feedback };
    },

    /**
     * Activity: Generates critical questions a venture capitalist might ask about a business plan.
     * The AI is prompted to return a structured JSON response.
     * @param input - Contains the business plan string.
     * @returns An object containing an array of structured questions.
     */
    async generateBusinessPlanQuestions(
      input: BusinessPlanAnalysisInput,
    ): Promise<BusinessPlanQuestionsOutput> {
      const { businessPlan } = input;
      const questionsPrompt = `Based on the business plan provided, generate 3 critical questions a Venture Capitalist might ask. Categorize each question into 'Market', 'Finance', or 'Operations'. Your response must be a valid JSON array of objects, where each object has "id", "question", and "category" keys. Business Plan: "${businessPlan}"`;

      const questionsText = await agentService.generateText({ prompt: questionsPrompt });

      // Clean up potential markdown formatting from the AI response before parsing.
      const cleanedJson = questionsText.replace(/```json|```/g, '').trim();

      try {
        const questions: AIQuestion[] = JSON.parse(cleanedJson);
        return { questions };
      } catch (error) {
        // Log the malformed response and throw an error to fail the activity
        console.error('Failed to parse JSON response from AI for business plan questions.', {
            rawResponse: questionsText,
            cleanedResponse: cleanedJson,
            error,
        });
        throw new Error('AI returned a malformed JSON response for questions.');
      }
    },

    /**
     * Activity: Notifies the rest of the system that the business plan analysis is complete.
     * It emits an event to a Kafka topic. This can be used by other services to update a database,
     * send a user notification, etc., completing the saga.
     * @param input - Contains the userId and the results of the analysis.
     */
    async notifyAnalysisComplete(input: NotifyAnalysisCompleteInput): Promise<void> {
      const { userId, feedback, questions } = input;

      kafkaClient.emit('agent.business_plan_analysis.completed', {
        userId,
        feedback,
        questions,
        status: 'success',
      });
      // The `emit` method is fire-and-forget. We'll resolve the promise to signal completion.
      return Promise.resolve();
    },
  };
}
